import{_ as i,l as s,o as e,c as T,v as t,p as l,x as o,d as p,i as c,S as n}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"SCTP 对照","description":"","frontmatter":{"title":"SCTP 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sctp.md","filePath":"cs/sctp.md","lastUpdated":1789023840000}'),C={name:"cs/sctp.md"};function P(d,a,h,S,_,m){const r=s("Mermaid");return e(),T("div",null,[a[1]||(a[1]=t('<h1 id="sctp-对照" tabindex="-1">SCTP 对照 <a class="header-anchor" href="#sctp-对照" aria-label="Permalink to &quot;SCTP 对照&quot;">​</a></h1><div class="epigraph"><p>SCTP 原生多宿与多流，消息边界保留，四次握手带 cookie 抗 SYN 泛洪；不是 TCP 的选项补丁。</p><footer>—— 据 RFC 9260 SCTP；RFC 4960 历史整理</footer></div><p><a href="/cs/mptcp">MPTCP</a> 在 TCP 上打补丁。<a href="/cs/mptcp">上一课</a> 留下「为何不换协议」。缺口是 <strong>SCTP 对照</strong>：消息、多流无队头阻塞、INIT cookie。本课不把 QUIC 0-RTT 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信令（SS7 over IP）要多宿故障切换、要记录边界。TCP 是字节流，粘包后课才说。SCTP：DATA 块有流 ID，一流失序不挡另一流——对照后课 HTTP/2 与 QUIC。关联（association）可绑多地址。四次握手：INIT-ACK 带 cookie，状态在客户端回 COOKIE-ECHO 后才占 TCB，对象同 SYN cookies，但是一等公民。</p><p>不要把 SCTP 写成互联网默认：NAT 与中间盒支持远差于 TCP/UDP。</p><p><span class="marginnote">RFC 9260 现行。WebRTC 数据通道曾用 SCTP over DTLS。本课对照，不推部署。</span></p><h3 id="原生多流多宿" tabindex="-1">原生多流多宿 <a class="header-anchor" href="#原生多流多宿" aria-label="Permalink to &quot;原生多流多宿&quot;">​</a></h3><p>消息边界保留，cookie 握手抗泛洪。NAT 支持差于 TCP/UDP。Web 路径上 QUIC 更常见。不是默认互联网运输。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表：TCP / MPTCP / SCTP / QUIC：单位、多径、握手、部署。画：多流 → 公共拥塞窗口（或按实现）。与 UDP：SCTP 可靠可选，还有部分可靠扩展点名。</p>',11)),(e(),l(n,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20STR%5B%22%E5%A4%9A%E6%B5%81%22%5D%0A%20%20STR%20--%3E%20ASSOC%5B%22%E5%A4%9A%E5%AE%BF%E5%85%B3%E8%81%94%22%5D%0A%20%20CK%5B%22INIT%20cookie%22%5D%20--%3E%20ANTI%5B%22%E6%8A%97%E6%B3%9B%E6%B4%AA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>拥塞仍 AIMD 族，BDP 同样适用。心跳是协议内，比 TCP keepalive 更一等。不走 TSO 惯例路径，卸载少。RTO 与无线误码同样痛。EVPN 等与 SCTP 无关。</p><p>队头：SCTP 流避免传输 HOL，应用仍可自己造依赖。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SCTP 认证块全文。QUIC 流与 0-RTT 是下一课。后课默认：SCTP 是另一运输；Web 路径上 QUIC 更常见。</p><p>防火墙只放 80/443 时 SCTP 出不去。</p><p>上一课留下的缺口在本课收口；「SCTP 对照」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/quic-streams-0rtt">QUIC 流与 0-RTT</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>消息+多流+多宿是原生能力。</li><li>Cookie 握手抗半开洪泛。</li><li>部署受 NAT/中间盒约束。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9260。</li></ul>',10))])}const E=i(C,[["render",P]]);export{u as __pageData,E as default};
